llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "In fasting healthy humans, azosemide, a close furosemide analog, has an absolute oral bioavailability of ~20.4%, just meeting the ≥20% threshold; this is weak supportive evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Azosemide bioavailability estimated from urinary excretion was only ~10% in patients, providing contradictory evidence; however, this estimate lacked paired IV AUC and is less reliable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Bumetanide, a sulfamoylbenzoic acid loop diuretic closely related to furosemide, has an absolute oral bioavailability of 80% in normal subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Hydrochlorothiazide, a sulfonamide diuretic sharing the sulfamoylbenzene motif, has an absolute oral bioavailability of 66–75% in healthy adults, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tolfenamic acid, a halogenated anthranilic acid, has an absolute oral bioavailability of 60.4% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Meclofenamate, a halogenated anthranilic acid, has oral bioavailability above 85% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Metolazone, a sulfonamide diuretic, is available in an approximately 100% bioavailable form, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is furosemide. Although the closest high-similarity record is a furosemide acyl glucuronide metabolite rather than parent drug, multiple structurally related loop diuretics and sulfonamide/anthranilic acid drugs with direct human absolute bioavailability measurements support F ≥20%: bumetanide ~80%, hydrochlorothiazide ~60–80%, tolfenamic acid ~60%, meclofenamate >85%, and metolazone ~100%. Azosemide, a close analog, is borderline/low (~10–20%), but its mixed and less reliable estimates do not outweigh the consistent high-F evidence from the broader analog family. Therefore, high oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct experimental record for furosemide parent bioavailability; the highest-similarity record (C06) is for furosemide acyl glucuronide metabolite, not parent F.",
    "Azosemide data are mixed (10% vs 20.4%) and some estimates are from urinary excretion without paired IV AUC, limiting certainty.",
    "Fasted-state condition is specified for the query, but not all supporting records explicitly report fasting conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

